const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/custom_field_definitions/%7Bcustom_field_definition_id%7D/custom_field_lov_entries',
  qs: {
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE',
    'filters[start_with]': 'SOME_STRING_VALUE',
    'filters[active]': 'SOME_BOOLEAN_VALUE',
    'filters[label_with]': 'SOME_STRING_VALUE'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/custom_field_definitions/%7Bcustom_field_definition_id%7D/custom_field_lov_entries?page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE&filters%5Bstart_with%5D=SOME_STRING_VALUE&filters%5Bactive%5D=SOME_BOOLEAN_VALUE&filters%5Blabel_with%5D=SOME_STRING_VALUE"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}
